<script setup lang="ts">
import ResourceRecovery from './ResourceRecovery.vue';
import {resourceApi} from '#/api/creative-video/resources';
import {ref} from 'vue';
import {ElInput,ElButton,ElMessage,ElTag} from 'element-plus';
import {studioStorage} from '#/api/creative-video/storage';
import {loadUnderstanding,saveUnderstanding} from '#/api/creative-video/understanding';
import type {Understanding} from '#/api/creative-video/understanding';
import {allowed} from '#/api/creative-video/permissions';
const props=defineProps<{projectId:number}>();const document=ref(loadUnderstanding(props.projectId));const history=ref<Understanding[]>(JSON.parse(studioStorage.getItem(`vidcraft-understanding-history-${props.projectId}`)||'[]'));
function save(confirm=false){try{document.value=saveUnderstanding(props.projectId,document.value,confirm);history.value=JSON.parse(studioStorage.getItem(`vidcraft-understanding-history-${props.projectId}`)||'[]') as Understanding[];return true;}catch(e){ElMessage.warning((e as Error).message);return false;}}
function dirty(){document.value.confirmed=false;studioStorage.setItem(`vidcraft-understanding-dirty-${props.projectId}`,'true');}
const syncStatus=ref('本地草稿');const saving=ref(false);
async function submit(confirm=false){if(saving.value)return;saving.value=true;const success=save(confirm);if(!success){saving.value=false;return;}studioStorage.setItem(`vidcraft-understanding-dirty-${props.projectId}`,'true');try{syncStatus.value='正在保存服务端';const fingerprint=JSON.stringify(document.value);const result=await resourceApi.save(props.projectId,'understanding',JSON.parse(fingerprint) as Understanding,confirm);if(JSON.stringify(document.value)!==fingerprint){syncStatus.value='内容在同步期间已变化，请重新保存';return;}syncStatus.value=`服务端 R${result.revision} ${result.confirmed?'已确认':'已保存'}`;studioStorage.removeItem(`vidcraft-understanding-dirty-${props.projectId}`);}catch{document.value.confirmed=false;studioStorage.setItem(`vidcraft-understanding-${props.projectId}`,JSON.stringify(document.value));syncStatus.value='服务端保存失败或冲突，本地内容保留，请勿继续审核';ElMessage.warning(syncStatus.value);}finally{saving.value=false;}}
</script>
<template><section><ResourceRecovery :project-id="projectId" kind="understanding"/><p role="status">{{ syncStatus }}</p><ElTag>产品理解 R{{ document.revision }} · {{ document.confirmed?'已确认':'待核实' }}</ElTag><p>候选洞察为 Mock 启发式推测；拥有者确认也不等于外部市场验证。</p><fieldset :disabled="!allowed('edit')"><label v-for="field in (['positioning','category','persona','decisionMaker','oldWay','newWay','features','risks','sensitive'] as const)" :key="field">{{ {positioning:'一句话产品定位',category:'产品类别',persona:'目标用户与使用场景',decisionMaker:'决策者与使用者',oldWay:'传统方式',newWay:'产品差异',features:'核心功能与资料依据',risks:'风险与不确定性',sensitive:'不适合拍摄及禁止宣传内容'}[field] }}<ElInput v-model="document[field]" type="textarea" @input="dirty"/></label><h3>痛点候选与证据审核</h3><article v-for="insight in document.insights" :key="insight.id"><label v-for="field in (['scenario','pain','emotion','feature','evidence'] as const)" :key="field">{{ {scenario:'具体场景',pain:'痛点',emotion:'情绪',feature:'关联功能',evidence:'证据来源或摘录'}[field] }}<ElInput v-model="insight[field]" @input="dirty"/></label><select v-model="insight.level" @change="dirty"><option value="verified">资料验证</option><option value="user_confirmed">拥有者确认</option><option value="hypothesis">推测</option><option value="unsupported">无依据</option></select><label><input v-model="insight.prohibited" type="checkbox" @change="dirty"/>禁止用于广告主张</label><ElButton @click="document.insights=document.insights.filter(i=>i.id!==insight.id);dirty()">删除候选</ElButton></article><ElButton @click="document.insights.push({id:Math.max(0,...document.insights.map(i=>i.id))+1,scenario:'',pain:'',emotion:'',feature:'',evidence:'',level:'hypothesis',prohibited:false});dirty()">增加痛点候选</ElButton><ElButton @click="submit()">保存理解草稿</ElButton></fieldset><ElButton type="primary" :loading="saving" :disabled="!allowed('review') || saving" @click="submit(true)">确认结构化产品理解</ElButton><details><summary>理解修订历史</summary><div v-for="h in history" :key="h.revision"><p>R{{ h.revision }} · {{ h.date }} · {{ h.positioning }}</p><ElButton :disabled="!allowed('edit')" @click="document=JSON.parse(JSON.stringify(h));dirty();submit()">恢复为新草稿</ElButton></div></details></section></template>
<style scoped>section{margin:24px 0}fieldset{border:0;padding:0}label{display:block;margin:16px 0}article{padding:20px;border:1px solid var(--el-border-color);border-radius:10px;margin:18px 0}p{color:var(--el-text-color-secondary);margin:14px 0}details{margin-top:24px}</style>
